[k] Stage 2/8 — 反反调试环境（内核级 + 进程内双层）

───────────────── RELOADED ─────────────────

壳还没跑起来就先被打死是最常见的时间损失来源。VMProtect 3.x 的反调试分三层，这一层把它们一次性铺掉，后面所有断点都在干净环境里下。

**层次与对应手段**

| 检测层 | 典型手段 | 处理 |
|---|---|---|
| PEB 标志 | `BeingDebugged`、`NtGlobalFlag`、Heap `Flags/ForceFlags` | ScyllaHide 的 `HideFromDebugger` 插件 + 进程内二次清零 |
| API 查询 | `IsDebuggerPresent`、`NtQueryInformationProcess(0x7/0x1E/0x3E)`、`CheckRemoteDebuggerPresent`、`NtQuerySystemInformation(0x35)` | ScyllaHide 插件；进程内 IAT 换指针 |
| 线程隐藏 | `NtSetInformationThread(0x11)` | ScyllaHide 的 `NtSetInformationThread` 插件 |
| 窗口枚举 | `EnumWindows` 找 `"x64dbg"/"OllyDbg"/"Immunity"` | ScyllaHide `WindowHide` + 进程内 `EnumWindows` 过滤 |
| 调试输出 | `OutputDebugString` 反探测 | IAT 换成恒返回 TRUE 的桩 |
| **时间测量** | `rdtsc`/`cpuid`、`QPC`、`GetTickCount`、`timeGetTime` 成对采样比对 | **ScyllaHide 管不了**，必须自己做「单调平稳计数器」+ 对 `rdtsc` 处下断点改跳转（下面有） |
| **SEH/VEH 链** | 壳装自己的异常处理器，检查是否先被调试器吃掉 | 内核级隐藏（TitanHide/ScyllaHideDK）或手动摘链 |
| **内核对抗**（重保护配置） | `DRIVER`、内核钩子扫描 | VM 内核级隐藏驱动，段尾给了 |

**Step 2.1 装工具（调试器 + 插件，宿主机或同架构 Windows）**

```bash
# 调试器本体：x64dbg 正式版（自带 x32dbg）
mkdir -p /work/tool/dbg && cd /work/tool/dbg
# 下载 x64dbg 官方 snapshot，解压后 x64dbg.exe 放到 /work/tool/dbg
# ScyllaHide 插件（最后版本，支持 x64dbg 2024+）
mkdir -p /work/tool/dbg/plugins
#   把 ScyllaHide 的 plugins.ini 与 ScyllaHide*.dp32/.dp64 拷进 plugins/
# 附加工具
pip3 install pefile capstone
```

**Step 2.2 插件配置 —— 写死一份，别用默认值**

```ini
; /work/tool/dbg/plugins/plugins.ini
[ScyllaHide]
EnableAdvancedOptions=1
; ---- 关掉会打断你的东西 ----
PauseUponBreakpoint=0
ShowJumpToEntryPointDialog=0
EnableDllNotification=1
; ---- 反反调试核心 ----
HideFromDebugger=1
NtSetInformationThread=1
NtClose=1
FindWindow=1
NtQuerySystemInformation=1
NtQueryObject=1
NtQueryInformationProcess=1
OutputDebugString=1
NtSetInformationProcess=1
NtQueryPerformanceCounter=1
NtQueryVirtualMemory=1
SetLastError=1
SuspendThread=1
; ---- 对付窗口枚举 / 调试对象 ----
WindowHide=1
UnhookNtQuerySystemInformation=1
DebuggerObjects=1
; ---- 时间类：全部交给下面自写的 dbgfix.dll，ScyllaHide 这几项要关掉 ----
AntiAntiDebugging_VM=0
```

关键两条：`PauseUponBreakpoint=0`（不停，免得每断一次都让壳以为被调试节奏异常），`AntiAntiDebugging_VM=0`（VMP 自带反反调试和插件的会互相打架）。

**Step 2.3 进程内补丁 DLL —— 自己动手的部分（时间 + 残留 API）**

ScyllaHide 的 `NtQueryPerformanceCounter`/`NtSetLastError` 处理是「回放上一段真实时间」，在 VMP 3.x 的成对采样下仍会露出抖动。下面这份 DLL 自己维护一个**严格单调、步长受控**的计数器，并把 PEB/Heap 标志二次清零、把关键 IAT 项换成自己的实现。

```c
/* /work/tool/dbg/dbgfix.c  —  build: see Step 2.4 */
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <stdio.h>
#include <string.h>

typedef LONG   NTSTATUS_;
typedef NTSTATUS_ (NTAPI *PFN_NtQI)(HANDLE, DWORD, PVOID, ULONG, PULONG);
typedef NTSTATUS_ (NTAPI *PFN_NtSI)(DWORD, PVOID, ULONG, PULONG);
typedef NTSTATUS_ (NTAPI *PFN_NtSTI)(HANDLE, DWORD, PVOID, ULONG);

static FILE *g_log = NULL;
static void L(const char *fmt, ...) {
    char b[512]; va_list ap; __try { va_start(ap, fmt);
        vsnprintf(b, sizeof b, fmt, ap); va_end(ap); } __except (EXCEPTION_EXECUTE_HANDLER) { return; }
    OutputDebugStringA("[dbgfix] "); OutputDebugStringA(b); OutputDebugStringA("\n");
    if (g_log) { fputs(b, g_log); fputc('\n', g_log); fflush(g_log); }
}

/* ---------- 1. 平稳计数器：QPC 原始值 -> 受控单调序列 ---------- */
static volatile LONG64 g_last_qpc = 0, g_last_ms = 0;
static LONG64  g_tick_hz = 0;

static void tick_init(void) {
    LARGE_INTEGER f; HMODULE k = GetModuleHandleA("kernel32.dll");
    typedef BOOL (WINAPI *QPF)(LARGE_INTEGER*);
    QPF qpf = (QPF)GetProcAddress(k, "QueryPerformanceFrequency");
    g_tick_hz = (qpf && qpf(&f)) ? f.QuadPart : 10000000LL;
    if (g_tick_hz <= 0) g_tick_hz = 10000000LL;
}
static LONG64 steady_qpc(void) {          /* 步长夹在 [1, 10ms] */
    LARGE_INTEGER q; QueryPerformanceCounter(&q);
    LONG64 last = InterlockedCompareExchange64(&g_last_qpc, 0, 0);
    if (last == 0) { InterlockedExchange64(&g_last_qpc, 1); return 1; }
    LONG64 d = q.QuadPart - last;
    LONG64 cap = g_tick_hz / 100;         /* 10ms */
    if (d <= 0 || d > cap) d = cap / 10;  /* 抖动/倒退/巨跳 -> 换成 1ms */
    LONG64 nxt = last + d;
    InterlockedExchange64(&g_last_qpc, nxt);
    return nxt;
}
static DWORD steady_ms(void) {
    LARGE_INTEGER q; QueryPerformanceCounter(&q);
    LONG64 last = InterlockedCompareExchange64(&g_last_ms, 0, 0);
    if (last == 0) { InterlockedExchange64(&g_last_ms, 100); return 100; }
    LONG64 d = ((q.QuadPart - last) * 1000) / g_tick_hz;   /* -> ms */
    if (d <= 0 || d > 250) d = 10;
    DWORD nxt = (DWORD)(last + d);
    InterlockedExchange64(&g_last_ms, (LONG64)nxt);
    return nxt;
}

/* ---------- 2. 我方替身实现 ---------- */
static BOOL WINAPI h_IsDebuggerPresent(void) { return FALSE; }
static BOOL WINAPI h_CheckRemoteDebuggerPresent(HANDLE p, BOOL *out) { if (out) *out = FALSE; return TRUE; }

static NTSTATUS_ NTAPI h_NtQI(HANDLE h, DWORD cls, PVOID inf, ULONG len, PULONG ret) {
    switch (cls) {
    case 0x07: /* ProcessDebugPort        */
    case 0x1E: /* ProcessDebugObjectHandle */
    case 0x1F: /* ProcessDebugFlags        */
    case 0x3E: {                        /* ProcessDebugPort(64) 变体 */
        if (inf && len >= 4) *(ULONG*)inf = 0;
        if (ret) *ret = 4;
        return (NTSTATUS_)0;
    }
    }
    static PFN_NtQI real = NULL;
    if (!real) real = (PFN_NtQI)GetProcAddress(GetModuleHandleA("ntdll.dll"), "NtQueryInformationProcess");
    return real ? real(h, cls, inf, len, ret) : (NTSTATUS_)0;
}
static NTSTATUS_ NTAPI h_NtSI(DWORD cls, PVOID inf, ULONG len, PULONG ret) {
    if (cls == 0x35) {                   /* SystemKernelDebuggerInformation */
        if (inf && len >= 8) *(ULONG*)inf = 0;
        if (ret) *ret = 8;
        return (NTSTATUS_)0;
    }
    static PFN_NtSI real = NULL;
    if (!real) real = (PFN_NtSI)GetProcAddress(GetModuleHandleA("ntdll.dll"), "NtQuerySystemInformation");
    return real ? real(cls, inf, len, ret) : (NTSTATUS_)0;
}
static NTSTATUS_ NTAPI h_NtSTI(HANDLE t, DWORD cls, PVOID inf, ULONG len) {
    if (cls == 0x11) return (NTSTATUS_)0; /* 拦下 ThreadHideFromDebugger */
    static PFN_NtST
